using Microsoft.ML;
using ChurnPredictor.Models;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// Train model at startup
var mlContext = new MLContext(seed: 0);

var csvPath = Path.Combine(app.Environment.ContentRootPath, "Data", "customers.csv");
var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(csvPath, hasHeader: true, separatorChar: ',');

var pipeline = mlContext.Transforms.CustomMapping<CustomerData, ChurnedLabel>(
        (input, output) => { output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase); },
        contractName: "ChurnedMapping")
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerData.Age),
        nameof(CustomerData.Income),
        "RegionEncoded",
        nameof(CustomerData.PurchaseHistory)))
    .Append(mlContext.BinaryClassification.Trainers.FastTree());

var model = pipeline.Fit(dataView);

// Evaluate
var predictions = model.Transform(dataView);
var metrics = mlContext.BinaryClassification.Evaluate(predictions);
Console.WriteLine($"Accuracy: {metrics.Accuracy:P2}");
Console.WriteLine($"AUC:      {metrics.AreaUnderRocCurve:P2}");
Console.WriteLine($"F1 Score: {metrics.F1Score:P2}");

var predictionEngine = mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(model);

app.MapGet("/", () => "Churn Predictor API");

app.MapPost("/predict", (PredictRequest request) =>
{
    var input = new CustomerData
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region ?? string.Empty,
        PurchaseHistory = request.PurchaseHistory
    };

    var prediction = predictionEngine.Predict(input);

    return Results.Json(new
    {
        Churn = prediction.PredictedLabel ? "Yes" : "No",
        prediction.Probability,
        prediction.Score
    });
});

app.Run();

public class ChurnedLabel
{
    public bool Label { get; set; }
}

public class PredictRequest
{
    public float Age { get; set; }
    public float Income { get; set; }
    public string? Region { get; set; }
    public float PurchaseHistory { get; set; }
}

